describe('File Download Functionality', () => {
  beforeEach(() => {
    cy.visit('/files');
  });

  it('should successfully download a previously uploaded file', () => {
    // Intercept the file download API call
    cy.intercept('GET', '/api/files/download/12345').as('downloadFile');

    // Verify file exists in the list
    cy.get('[data-testid="file-item-12345"]').should('be.visible');
    cy.get('[data-testid="file-name-12345"]').should('contain', 'Sample Document');

    // Click the download button
    cy.get('[data-testid="download-btn-12345"]').click();

    // Wait for the download to complete
    cy.wait('@downloadFile');

    // Verify download was initiated
    cy.get('[data-testid="download-status-12345"]').should('contain', 'Downloading');

    // Verify download file appears in browser downloads
    cy.get('[data-testid="download-file-12345"]').should('be.visible');
    cy.get('[data-testid="download-file-12345"]').should('contain', 'Sample Document');

    // Verify file is downloaded
    cy.get('[data-testid="download-file-12345"]').should('have.attr', 'download');

    // Verify file is saved in the correct location
    cy.get('[data-testid="download-file-12345"]').should('have.attr', 'href');
    cy.get('[data-testid="download-file-12345"]').should('contain', '/downloads/Sample Document.pdf');

    // Verify file is accessible
    cy.get('[data-testid="download-file-12345"]').should('be.visible');
  });

  it('should handle failed file download due to server error', () => {
    // Intercept the file download API call with a 500 error
    cy.intercept('GET', '/api/files/download/99999', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('downloadFileError');

    // Verify file exists in the list
    cy.get('[data-testid="file-item-99999"]').should('be.visible');

    // Click the download button
    cy.get('[data-testid="download-btn-99999"]').click();

    // Wait for the failed download attempt
    cy.wait('@downloadFileError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to download file');

    // Verify download button is still clickable
    cy.get('[data-testid="download-btn-99999"]').should('be.visible');

    // Verify file is not downloaded
    cy.get('[data-testid="download-file-99999"]').should('not.exist');

    // Verify retry button is available
    cy.get('[data-testid="retry-btn-99999"]').should('be.visible');
  });
});
